cfg.thread_num = thread_num;
cfg.log_level = log_level;
cfg.log_mask = log_mask;
cfg.log_file_path = use_log_file ? s_log.c_str() : (const char*)NULL;
cfg.log_file_days = log_file_days;

cfg.ini_is_path = ini_is_path;
cfg.ini = use_ini ? s_ini.c_str() : (const char*)NULL;

cfg.ssl_is_path = ssl_is_path;
cfg.ssl = use_ssl ? s_ssl.c_str() : (const char*)NULL;
cfg.ssl_pwd = use_ssl_pwd ? s_sslpwd.c_str() : (const char*)NULL;

// Invoke target; must be called before other APIs.
mk_env_init(&cfg);

// Mark environment initialized for downstream stubs
FUZZ_SET_ATTR_INT_GLOBAL("env_inited", 1);

// Enforce environment initialized before stopping servers to avoid undefined behavior.
if (FUZZ_GET_ATTR_INT_GLOBAL("env_inited") != 1) { FUZZ_BAIL(); }

// Shut down all servers started by the library.
mk_stop_all_server();

// Initialize environment via scalar-parameter variant.
// Generate constrained values mirroring mk_env_init field constraints.
int thread_num = (int)(*FUZZ_PARAM(unsigned int) % 8) + 1; // 1..8
int log_level = (int)(*FUZZ_PARAM(unsigned int) % 5); // 0..4
int log_mask = (int)(*FUZZ_PARAM(unsigned int)); // bitmask
int log_file_days = (int)(*FUZZ_PARAM(unsigned int) % 31); // 0..30

int ini_is_path = (int)(*FUZZ_PARAM(unsigned int) % 2);
int ssl_is_path = (int)(*FUZZ_PARAM(unsigned int) % 2);

// Optional strings can be NULL or provided
int use_log_file = (int)(*FUZZ_PARAM(unsigned int) % 2);
int use_ini = (int)(*FUZZ_PARAM(unsigned int) % 2);
int use_ssl = (int)(*FUZZ_PARAM(unsigned int) % 2);
