} else {
    // Build a valid mk_events table; unused callbacks can be NULL
    mk_events ev = {};

    // Provide a small set of valid no-op callbacks with exact signatures to exercise API paths.
    auto cb_media_changed = +[](int regist, const mk_media_source sender) {
