import random
import string
from typing import List

# This generator targets a generic string data type consumed by multiple stubs via
# FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME. We aim to produce valid, interesting strings
# that exercise different code paths: paths, URLs, JSON, SDP-like, headers, credentials,
# short/long lengths, and binary-safe payloads. The result is a bytes buffer holding
# one logically self-contained string. The fuzzing harness can slice/consume multiple
# strings from the same buffer as needed.

MAX_OUT = 4096

def _rand_hostname(r: random.Random) -> str:
    labels = []
    nlab = r.randint(1, 4)
    for _ in range(nlab):
        L = r.randint(1, 10)
        s = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(L))
        labels.append(s)
    tlds = ["com", "net", "org", "local", "lan"]
    return '.'.join(labels + [r.choice(tlds)])

def _rand_ipv4(r: random.Random) -> str:
    return '.'.join(str(r.randint(0, 255)) for _ in range(4))

def _rand_path(r: random.Random) -> str:
    parts = []
    n = r.randint(1, 5)
    for _ in range(n):
        L = r.randint(1, 8)
        seg = ''.join(r.choice(string.ascii_letters + string.digits + "_-.") for _ in range(L))
        parts.append(seg)
    root = "/" if r.random() < 0.7 else ""
    return root + '/'.join(parts)

def _rand_query(r: random.Random, n_pairs: int) -> str:
    pairs = []
    for _ in range(n_pairs):
        kL = r.randint(1, 6)
        vL = r.randint(0, 10)
        k = ''.join(r.choice(string.ascii_lowercase) for _ in range(kL))
        v = ''.join(r.choice(string.ascii_letters + string.digits + "-_.") for _ in range(vL))
        pairs.append(f"{k}={v}")
    return '&'.join(pairs)

def _rand_url(r: random.Random) -> str:
    schemes = ["http", "https", "rtsp", "rtsps", "rtmp", "rtmps", "rtc"]
    scheme = r.choice(schemes)
    host = _rand_hostname(r) if r.random() < 0.6 else _rand_ipv4(r)
    port = f":{r.randint(1,65535)}" if r.random() < 0.6 else ""
    path = _rand_path(r)
    q = "?" + _rand_query(r, r.randint(0, 4)) if r.random() < 0.5 else ""
    return f"{scheme}://{host}{port}{path}{q}"

def _rand_filename(r: random.Random) -> str:
    # Generate plausible absolute/relative file paths used by *_FILENAME
    if r.random() < 0.5:
        base = _rand_path(r)
    else:
        base = "./" + _rand_path(r).lstrip('/')
    if r.random() < 0.5:
        ext = r.choice([".log", ".ini", ".cfg", ".pem", ".crt", ".key", ".mp4", ".txt"])
    else:
        ext = ""
    return base + ext

def _rand_json(r: random.Random) -> str:
    # Small JSON object with media-like keys
    o = {
        "vhost": "__defaultVhost__",
        "app": r.choice(["live", "vod", "app"]),
        "stream": ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(3,10))),
        "hls": r.choice([0,1]),
        "mp4": r.choice([0,1]),
        "options": {
            "protocol_timeout_ms": r.randint(100, 5000),
            "media_timeout_ms": r.randint(100, 5000),
        }
    }
    # Manual JSON to avoid imports beyond stdlib json (though allowed); keep deterministic order
    def dumps(x):
        if isinstance(x, dict):
            items = []
            for k in x.keys():
                items.append(f'"{k}":{dumps(x[k])}')
            return "{" + ",".join(items) + "}"
        if isinstance(x, str):
            s = x.replace('"', '\\"')
            return f'"{s}"'
        if isinstance(x, bool):
            return "true" if x else "false"
        if isinstance(x, int):
            return str(x)
        return 'null'
    return dumps(o)

def _rand_http_header_block(r: random.Random) -> str:
    # Minimal HTTP request header block
    methods = ["GET", "POST", "HEAD"]
    m = r.choice(methods)
    path = _rand_path(r)
    ver = r.choice(["HTTP/1.0", "HTTP/1.1"])
    lines = [f"{m} {path} {ver}"]
    headers = [
        ("Host", _rand_hostname(r)),
        ("User-Agent", "mk-fuzzer/1.0"),
        ("Accept", "*/*"),
    ]
    if r.random() < 0.5:
        headers.append(("Authorization", "Basic dXNlcjpwYXNz"))
    for k,v in headers:
        lines.append(f"{k}: {v}")
    lines.append("")
    lines.append("")
    return "\r\n".join(lines)

def _rand_sdp_offer(r: random.Random) -> str:
    # Simple SDP-like text for WebRTC paths
    o = []
    o.append("v=0")
    o.append(f"o=- {r.randint(100000,999999)} 2 IN IP4 127.0.0.1")
    o.append("s=-")
    o.append("t=0 0")
    o.append("a=group:BUNDLE 0 1")
    o.append("m=application 9 UDP/DTLS/SCTP webrtc-datachannel")
    o.append("c=IN IP4 0.0.0.0")
    o.append("a=mid:0")
    o.append("a=sctpmap:5000 webrtc-datachannel 1024")
    return "\r\n".join(o) + "\r\n"

def _rand_creds(r: random.Random) -> str:
    user = ''.join(r.choice(string.ascii_letters + string.digits) for _ in range(r.randint(3,12)))
    pwd = ''.join(r.choice(string.ascii_letters + string.digits + "!@#$_-") for _ in range(r.randint(3,16)))
    return f"{user}:{pwd}"

def _rand_printable_blob(r: random.Random, n: int) -> str:
    alphabet = string.ascii_letters + string.digits + " \t\r\n-_./:+=,;@[]{}()"
    return ''.join(r.choice(alphabet) for _ in range(n))

def _rand_binary_blob(r: random.Random, n: int) -> bytes:
    # Include zeroes and high bytes
    return bytes(r.getrandbits(8) for _ in range(n))

def _mix_sections(r: random.Random) -> bytes:
    # Build a compound buffer containing multiple newline-separated items to satisfy
    # consumers that pull multiple FUZZ_PARAM_STR from a single input buffer.
    sections: List[bytes] = []
    # Always start with a plausible URL or filename to help many stubs
    if r.random() < 0.5:
        sections.append(_rand_url(r).encode('utf-8'))
    else:
        sections.append(_rand_filename(r).encode('utf-8'))

    # Add a SDP-like block sometimes (for WebRTC answer APIs)
    if r.random() < 0.5:
        sections.append(_rand_sdp_offer(r).encode('utf-8'))

    # Add an HTTP header block sometimes (for parser-related paths)
    if r.random() < 0.5:
        sections.append(_rand_http_header_block(r).encode('utf-8'))

    # Add JSON config chunk sometimes
    if r.random() < 0.5:
        sections.append(_rand_json(r).encode('utf-8'))

    # Add credentials and SSRC-like decimal
    if r.random() < 0.7:
        sections.append(_rand_creds(r).encode('utf-8'))
        sections.append(str(r.randint(1, 2**31-1)).encode('ascii'))

    # Add some short tokens expected by options (e.g., integers as strings)
    for _ in range(r.randint(2, 6)):
        if r.random() < 0.6:
            sections.append(str(r.randint(0, 10000)).encode('ascii'))
        else:
            s = _rand_printable_blob(r, r.randint(1, 32)).encode('utf-8')
            sections.append(s)

    # Sometimes include a small binary tail to exercise binary-safe consumers
    if r.random() < 0.3:
        sections.append(_rand_binary_blob(r, r.randint(8, 64)))

    # Join with newlines to delineate strings cleanly
    out = b"\n".join(sections)
    if len(out) > MAX_OUT:
        out = out[:MAX_OUT]
    return out

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a profile of content
    choice = r.random()
    if choice < 0.15:
        s = _rand_filename(r).encode('utf-8')
    elif choice < 0.30:
        s = _rand_url(r).encode('utf-8')
    elif choice < 0.45:
        s = _rand_http_header_block(r).encode('utf-8')
    elif choice < 0.60:
        s = _rand_sdp_offer(r).encode('utf-8')
    elif choice < 0.75:
        s = _rand_json(r).encode('utf-8')
    elif choice < 0.90:
        # Binary-safe chunk with printable prefix
        prefix = _rand_printable_blob(r, r.randint(4, 32)).encode('utf-8')
        blob = _rand_binary_blob(r, r.randint(16, 128))
        s = prefix + b"\n" + blob
    else:
        s = _mix_sections(r)

    if len(s) > MAX_OUT:
        s = s[:MAX_OUT]
    return s

import random
import string
from typing import List

# Data type: configuration value (string). Used by various *_set_option APIs.
# This generator returns a bytes buffer that will be used by FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME
# in the harness. We want to produce interesting, valid configuration values that cover:
# - Plain ASCII words (usernames, adapters)
# - Numeric strings (integers in ranges used by stubs)
# - Booleans encoded as 0/1
# - Floating-point speeds (e.g., 0.5, 1.0, 2.0)
# - Network adapter-like tokens
# - Short passwords/usernames without newlines
# - JSON-like snippets to exercise value parsing paths
# - Edge-case lengths but <= 4096 bytes

NUMERIC_KEYS = [
    "protocol_timeout_ms",
    "media_timeout_ms",
    "beat_interval_ms",
    "wait_track_ready",
    "rtp_type",
]
TEXT_KEYS = [
    "net_adapter",
    "rtsp_user",
    "rtsp_pwd",
]
SPECIAL_KEYS = [
    "rtsp_speed"
]

FLOAT_SPEEDS = ["0.25", "0.5", "1.0", "1.25", "1.5", "2.0", "4.0"]
ADAPTER_PREFIXES = ["eth", "enp", "wlan", "lo", "bond", "tun", "tap"]
USERNAMES = ["admin", "user", "root", "guest", "operator", "streamer"]
PASSWORD_TOKENS = ["123456", "admin", "password", "qwerty", "letmein", "zlm", "Pa55w0rd!"]

SAFE_ASCII = string.ascii_letters + string.digits + "-_:.@"


def _rand_int(rng: random.Random, lo: int, hi: int) -> int:
    return rng.randint(lo, hi)


def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def _rand_adapter(rng: random.Random) -> str:
    pref = _rand_choice(rng, ADAPTER_PREFIXES)
    if pref == "lo":
        return "lo"
    # produce names like eth0, enp3s0, wlan1, bond0, tun0, tap1
    if pref in ("eth", "wlan", "bond", "tun", "tap"):
        return f"{pref}{_rand_int(rng,0,9)}"
    # enpXsY style
    return f"enp{_rand_int(rng,0,9)}s{_rand_int(rng,0,9)}"


def _rand_username(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return _rand_choice(rng, USERNAMES)
    n = _rand_int(rng, 4, 12)
    return ''.join(rng.choice(SAFE_ASCII) for _ in range(n))


def _rand_password(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return _rand_choice(rng, PASSWORD_TOKENS)
    n = _rand_int(rng, 6, 16)
    chars = SAFE_ASCII + "!#$%^&*"  # avoid newline
    return ''.join(rng.choice(chars) for _ in range(n))


def _rand_numeric_string(rng: random.Random, key: str) -> str:
    if key == "rtp_type":
        return str(_rand_int(rng, 0, 1))  # 0 UDP, 1 TCP
    if key == "wait_track_ready":
        return str(_rand_int(rng, 0, 1))
    # timeouts/ms: keep small but varied
    if key in ("protocol_timeout_ms", "media_timeout_ms", "beat_interval_ms"):
        # Prefer 1..5000 as in stubs, sometimes 0 or larger edges
        roll = rng.random()
        if roll < 0.7:
            return str(_rand_int(rng, 1, 5000))
        elif roll < 0.85:
            return "0"
        else:
            return str(_rand_int(rng, 5001, 60000))
    # default fallback
    return str(_rand_int(rng, 0, 10000))


def _rand_speed(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return _rand_choice(rng, FLOAT_SPEEDS)
    # random float with 1-2 decimals between 0.1 and 4.0
    val = rng.uniform(0.1, 4.0)
    return f"{val:.2f}"


def _json_like(rng: random.Random) -> str:
    # Small JSON-like to exercise potential parsers; keep simple and single-line
    obj = {
        "enable_hls": str(_rand_int(rng, 0, 1)),
        "enable_mp4": str(_rand_int(rng, 0, 1)),
        "retry_count": str(_rand_int(rng, -1, 5)),
    }
    # Render without spaces to avoid issues
    parts = [f'"{k}":"{v}"' for k, v in obj.items()]
    return "{" + ",".join(parts) + "}"


def _random_text(rng: random.Random, max_len: int = 64) -> str:
    n = _rand_int(rng, 1, max_len)
    return ''.join(rng.choice(SAFE_ASCII) for _ in range(n))


def _build_kv_blob(rng: random.Random) -> str:
    # Construct a sequence of key=value lines that harness may split or use
    lines = []
    # Ensure coverage of different keys
    # text keys
    lines.append(f"net_adapter={_rand_adapter(rng)}")
    lines.append(f"rtsp_user={_rand_username(rng)}")
    lines.append(f"rtsp_pwd={_rand_password(rng)}")
    # numeric keys
    for k in NUMERIC_KEYS:
        lines.append(f"{k}={_rand_numeric_string(rng, k)}")
    # special float
    lines.append(f"rtsp_speed={_rand_speed(rng)}")
    # include a json-like value for extensibility testing
    if rng.random() < 0.5:
        lines.append(f"options_json={_json_like(rng)}")
    # add some arbitrary unknown keys to ensure robustness
    for _ in range(_rand_int(rng, 0, 3)):
        lines.append(f"x_{_random_text(rng, 6)}={_random_text(rng, 12)}")
    return "\n".join(lines)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose one of several value shapes
    mode = rng.randrange(6)
    if mode == 0:
        # Single numeric value (common for *_timeout_ms, rtp_type)
        key = _rand_choice(rng, NUMERIC_KEYS)
        val = _rand_numeric_string(rng, key)
        s = val
    elif mode == 1:
        # Single adapter token
        s = _rand_adapter(rng)
    elif mode == 2:
        # Username or password token
        s = _rand_choice(rng, [
            _rand_username(rng),
            _rand_password(rng)
        ])
    elif mode == 3:
        # Float speed string
        s = _rand_speed(rng)
    elif mode == 4:
        # JSON-like snippet
        s = _json_like(rng)
    else:
        # Multi-line kv blob to seed multiple FUZZ_PARAM_STR consumptions
        s = _build_kv_blob(rng)

    # Enforce size limit and sanitize newlines for single-value contexts, but allow them for blobs
    if mode in (0, 1, 2, 3, 4):
        s = s.replace("\n", "_").replace("\r", "_")
    if len(s) > 4096:
        s = s[:4096]
    if not s:
        s = "x"
    return s.encode("utf-8")
